//App.js
import React, { useState } from "react";
import Login from "../jsx/Login";
import Chat from "../jsx/Chat";
import "../css/App.css";

function App() {
    const [user, setUser] = useState(null);
    return user ? <Chat user={user} /> : <Login setUser={setUser} />;
}

export default App;
